#!/usr/bin/env python3
import argparse
import json
from pathlib import Path
from typing import Dict

DEFAULT_CONFIG = {
    "displayMode": "edit-message"
}


def load_config(path: str) -> Dict[str, str]:
    p = Path(path)
    if not p.exists():
        return dict(DEFAULT_CONFIG)
    try:
        data = json.loads(p.read_text())
    except Exception:
        return dict(DEFAULT_CONFIG)
    merged = dict(DEFAULT_CONFIG)
    merged.update({k: v for k, v in data.items() if isinstance(v, str)})
    return merged


def save_config(path: str, config: Dict[str, str]) -> None:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(config, ensure_ascii=False, indent=2))


def main() -> None:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="command", required=True)

    p_get = sub.add_parser("get")
    p_get.add_argument("config_path")

    p_set = sub.add_parser("set-mode")
    p_set.add_argument("config_path")
    p_set.add_argument("mode", choices=["edit-message", "new-message"])

    args = ap.parse_args()

    if args.command == "get":
        print(json.dumps(load_config(args.config_path), ensure_ascii=False, indent=2))
        return

    if args.command == "set-mode":
        cfg = load_config(args.config_path)
        cfg["displayMode"] = args.mode
        save_config(args.config_path, cfg)
        print(json.dumps(cfg, ensure_ascii=False, indent=2))
        return


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import argparse
import json
from pathlib import Path
from typing import Any, Dict, Optional

from file_browser_state import bump_menu_version, init_state, load_state, path_label, pop_path, push_path, save_state, set_live_message_id
from build_view import normalize, list_entries, paginate, build_items, is_within_root
from render_buttons import render_directory_buttons, render_file_action_buttons


def make_dir_prefix(path: Path) -> str:
    return f"d{abs(hash(str(path))) % 1000}"


def build_view_dict(root: Path, current: Path, prefix: str, page: int, page_size: int) -> Dict[str, Any]:
    entries = list_entries(root, current)
    page_entries, safe_page, total_pages = paginate(entries, page, page_size)
    start_index = (safe_page - 1) * page_size + 1
    return {
        "root": str(root),
        "path": str(current),
        "page": safe_page,
        "pageSize": page_size,
        "totalItems": len(entries),
        "totalPages": total_pages,
        "hasPrev": safe_page > 1,
        "hasNext": safe_page < total_pages,
        "items": build_items(page_entries, prefix, start_index=start_index)
    }


def find_item(state: Dict[str, Any], item_id: str) -> Optional[Dict[str, Any]]:
    for view in state.get("views", {}).values():
        for item in view.get("items", []):
            if item.get("id") == item_id:
                return item
    return None


def current_page_for(state: Dict[str, Any], path: Path) -> int:
    view = state.get("views", {}).get(str(path), {})
    return int(view.get("page", 1))


def render_directory_result(state: Dict[str, Any], root: Path, current: Path, page_size: int, page: int) -> Dict[str, Any]:
    prefix = "w" if current == root else make_dir_prefix(current)
    view = build_view_dict(root, current, prefix, page, page_size)
    state.setdefault("views", {})[str(current)] = view
    state["current"] = str(current)
    callback_prefix = "tfb_root" if current == root else f"tfb_dir_{prefix}"
    version = int(state.get("menuVersion", 1))
    return {
        "kind": "directory",
        "text": f"📂 文件浏览器\n当前位置：`{path_label(str(current))}`\n\n点下面按钮直接浏览：",
        "buttons": render_directory_buttons(view, callback_prefix, include_back=(current != root), version=version),
        "view": view,
        "state": state
    }


def open_root(state: Dict[str, Any], root: Path, page_size: int = 12) -> Dict[str, Any]:
    state["current"] = str(root)
    state["stack"] = []
    return render_directory_result(state, root, root, page_size, page=1)


def open_directory(state: Dict[str, Any], item_id: str, page_size: int = 12) -> Dict[str, Any]:
    item = find_item(state, item_id)
    if not item or item.get("type") != "dir":
        raise ValueError(f"Directory item not found: {item_id}")
    root = normalize(state["root"])
    current = normalize(state["current"])
    newp = normalize(item["path"])
    if not is_within_root(root, newp):
        raise PermissionError(f"Path escapes root: {newp}")
    push_path(state, str(current), str(newp))
    bump_menu_version(state)
    return render_directory_result(state, root, newp, page_size, page=1)


def open_file_actions(state: Dict[str, Any], item_id: str) -> Dict[str, Any]:
    item = find_item(state, item_id)
    if not item or item.get("type") != "file":
        raise ValueError(f"File item not found: {item_id}")
    state["selectedFileId"] = item_id
    state["selectedFilePath"] = item["path"]
    bump_menu_version(state)
    version = int(state.get("menuVersion", 1))
    return {
        "kind": "file-actions",
        "text": f"📄 文件操作\n目标：`{path_label(item['path'])}`\n\n选择你要的操作：",
        "buttons": render_file_action_buttons(item_id, version=version),
        "item": item,
        "state": state
    }


def go_back(state: Dict[str, Any], page_size: int = 12) -> Dict[str, Any]:
    prev = pop_path(state)
    root = normalize(state["root"])
    if not prev:
        bump_menu_version(state)
        return render_directory_result(state, root, root, page_size=page_size, page=1)
    prevp = normalize(prev)
    bump_menu_version(state)
    return render_directory_result(state, root, prevp, page_size, page=current_page_for(state, prevp))


def change_page(state: Dict[str, Any], direction: str, page_size: int = 12) -> Dict[str, Any]:
    root = normalize(state["root"])
    current = normalize(state["current"])
    current_page = current_page_for(state, current)
    target_page = current_page - 1 if direction == 'prev' else current_page + 1
    bump_menu_version(state)
    return render_directory_result(state, root, current, page_size, page=target_page)


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("command", choices=["open-root", "open-dir", "open-file-actions", "back", "page", "set-live-message"])
    ap.add_argument("state_path")
    ap.add_argument("--root")
    ap.add_argument("--item-id")
    ap.add_argument("--message-id")
    ap.add_argument("--direction", choices=["prev", "next"])
    ap.add_argument("--page-size", type=int, default=12)
    args = ap.parse_args()

    state_file = Path(args.state_path)
    if args.command == "open-root":
        if not args.root:
            raise SystemExit("--root is required for open-root")
        root = normalize(args.root)
        # Load existing state if it exists, otherwise initialize new
        if state_file.exists():
            state = load_state(str(state_file))
            state["current"] = str(root)
            state["stack"] = []
        else:
            state = init_state(str(root))
        result = open_root(state, root, page_size=args.page_size)
        save_state(str(state_file), result["state"])
        print(json.dumps(result, ensure_ascii=False, indent=2))
        return

    state = load_state(str(state_file))

    if args.command == "open-dir":
        if not args.item_id:
            raise SystemExit("--item-id is required for open-dir")
        result = open_directory(state, args.item_id, page_size=args.page_size)
    elif args.command == "open-file-actions":
        if not args.item_id:
            raise SystemExit("--item-id is required for open-file-actions")
        result = open_file_actions(state, args.item_id)
    elif args.command == "back":
        result = go_back(state, page_size=args.page_size)
    elif args.command == "page":
        if not args.direction:
            raise SystemExit("--direction is required for page")
        result = change_page(state, args.direction, page_size=args.page_size)
    elif args.command == "set-live-message":
        result = {"kind": "state-only", "state": set_live_message_id(state, args.message_id)}
    else:
        raise SystemExit(f"Unknown command: {args.command}")

    save_state(str(state_file), result["state"])
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
One-click browser dispatcher: generates plan, validates, returns exact payload.

Usage:
    python3 browser_dispatcher.py open-root
    python3 browser_dispatcher.py handle-callback <callback_data>

Note: Back and Close are handled via callback_data through handle-callback.
"""
import json
import sys
import os

# Add scripts dir to path
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, SCRIPT_DIR)

from run_browser_action import open_root, handle_callback
from send_plan import build_message_payload
from file_browser_state import default_runtime_state_path, default_workspace_root, load_state, save_state, set_live_message_id


STATE_PATH = str(default_runtime_state_path())
WORKSPACE_ROOT = str(default_workspace_root())


def run_action(action: str, callback_data: str = None):
    """Execute action and return a message-tool-ready payload."""

    if action == "open-root":
        plan = open_root(STATE_PATH, WORKSPACE_ROOT)
    elif action == "handle-callback":
        if not callback_data:
            return {"ok": False, "error": "callback_data required for handle-callback"}
        plan = handle_callback(STATE_PATH, callback_data)
    elif action == "update-message-id":
        # Update liveMessageId after successfully sending a menu
        # NOTE: Do NOT bump version here - that happens when menu content changes
        if not callback_data:
            return {"ok": False, "error": "message_id required for update-message-id"}
        state = load_state(STATE_PATH)
        set_live_message_id(state, callback_data)
        save_state(STATE_PATH, state)
        return {
            "ok": True,
            "toolAction": "noop",
            "message": f"Updated liveMessageId to {callback_data}, version now {state['menuVersion']}"
        }
    else:
        return {"ok": False, "error": f"Unknown action: {action}. Use 'open-root', 'handle-callback', or 'update-message-id'"}

    tool_action = plan.get("toolAction")

    if tool_action == "noop":
        return {
            "ok": True,
            "toolAction": "noop",
            "messageToolCall": None,
        }

    if tool_action == "delete":
        message_tool_call = {
            "action": "delete",
            "messageId": plan.get("messageId")
        }
        return {
            "ok": True,
            "toolAction": "delete",
            "messageToolCall": message_tool_call,
            "messageId": plan.get("messageId")
        }

    if tool_action == "send-file":
        message_tool_call = {
            "action": "send",
            "path": plan.get("path"),
            "caption": plan.get("caption"),
        }
        if plan.get("replyTo") is not None:
            message_tool_call["replyTo"] = plan.get("replyTo")
        if plan.get("filename") is not None:
            message_tool_call["filename"] = plan.get("filename")
        return {
            "ok": True,
            "toolAction": "send-file",
            "messageToolCall": message_tool_call,
            "path": plan.get("path"),
            "caption": plan.get("caption"),
            "replyTo": plan.get("replyTo")
        }

    if tool_action != "send":
        return {"ok": False, "error": f"Unsupported toolAction: {tool_action}"}

    if plan.get("buttons") is not None:
        validated = build_message_payload(plan)
        if not validated.get("ok"):
            return {"ok": False, "error": validated.get("error")}
        message_tool_call = dict(validated["payload"])
    else:
        message = plan.get("message")
        if not isinstance(message, str) or not message:
            return {"ok": False, "error": "message must be a non-empty string"}
        message_tool_call = {
            "action": "send",
            "message": message,
        }
        if plan.get("replyTo") is not None:
            message_tool_call["replyTo"] = plan.get("replyTo")

    post_send = {
        "updateLiveMessageId": bool(plan.get("replaceLiveMessage") or plan.get("liveMessageId") is None) and plan.get("buttons") is not None,
        "cleanupPreviousMessage": bool(plan.get("cleanupPreviousMessage")),
        "previousMessageId": plan.get("previousMessageId"),
    }

    return {
        "ok": True,
        "toolAction": "send",
        "messageToolCall": message_tool_call,
        "postSend": post_send,
        # Backward-compatible fields
        "message": message_tool_call["message"],
        "buttons": message_tool_call.get("buttons"),
        "replyTo": message_tool_call.get("replyTo"),
        "liveMessageId": plan.get("liveMessageId"),
        "previousMessageId": plan.get("previousMessageId"),
        "replaceLiveMessage": plan.get("replaceLiveMessage"),
        "cleanupPreviousMessage": plan.get("cleanupPreviousMessage")
    }


def main():
    if len(sys.argv) < 2:
        print(json.dumps({"ok": False, "error": "Usage: browser_dispatcher.py <action> [callback_data]"}))
        sys.exit(1)

    action = sys.argv[1]
    callback_data = sys.argv[2] if len(sys.argv) > 2 else None

    result = run_action(action, callback_data)
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import argparse
import json
from pathlib import Path
from typing import List, Dict


def normalize(path_str: str) -> Path:
    return Path(path_str).expanduser().resolve()


def is_within_root(root: Path, target: Path) -> bool:
    try:
        target.relative_to(root)
        return True
    except ValueError:
        return False


def list_entries(root: Path, current: Path) -> List[Path]:
    if not current.exists() or not current.is_dir():
        raise FileNotFoundError(f"Directory not found: {current}")
    if not is_within_root(root, current):
        raise PermissionError(f"Path escapes root: {current}")
    return sorted(current.iterdir(), key=lambda x: (x.is_file(), x.name.lower()))


def build_items(entries: List[Path], prefix: str, start_index: int = 1) -> List[Dict[str, str]]:
    items = []
    for i, entry in enumerate(entries, start=start_index):
        items.append({
            "id": f"{prefix}{i}",
            "name": entry.name,
            "path": str(entry),
            "type": "dir" if entry.is_dir() else "file"
        })
    return items


def paginate(entries: List[Path], page: int, page_size: int) -> tuple[List[Path], int, int]:
    total = len(entries)
    total_pages = max(1, (total + page_size - 1) // page_size)
    safe_page = max(1, min(page, total_pages))
    start = (safe_page - 1) * page_size
    end = start + page_size
    return entries[start:end], safe_page, total_pages


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("root")
    ap.add_argument("current")
    ap.add_argument("--prefix", default="i")
    ap.add_argument("--page", type=int, default=1)
    ap.add_argument("--page-size", type=int, default=12)
    args = ap.parse_args()

    root = normalize(args.root)
    current = normalize(args.current)
    entries = list_entries(root, current)
    page_entries, safe_page, total_pages = paginate(entries, args.page, args.page_size)
    items = build_items(page_entries, args.prefix)
    out = {
        "root": str(root),
        "path": str(current),
        "page": safe_page,
        "pageSize": args.page_size,
        "totalItems": len(entries),
        "totalPages": total_pages,
        "hasPrev": safe_page > 1,
        "hasNext": safe_page < total_pages,
        "items": items
    }
    print(json.dumps(out, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import time
from pathlib import Path
from typing import Any, Dict, Optional


DEFAULT_WORKSPACE_ROOT = Path.home() / ".openclaw" / "workspace"
DEFAULT_RUNTIME_STATE_PATH = DEFAULT_WORKSPACE_ROOT / ".openclaw" / "telegram-file-browser" / "state.json"


def default_workspace_root() -> Path:
    return DEFAULT_WORKSPACE_ROOT


def default_runtime_state_path() -> Path:
    return DEFAULT_RUNTIME_STATE_PATH


def path_label(path: str) -> str:
    p = Path(path).expanduser()
    try:
        return str(p).replace(str(Path.home()), "~", 1)
    except Exception:
        return str(p)


def load_state(path: str) -> Dict[str, Any]:
    p = Path(path)
    if not p.exists():
        return {}
    return json.loads(p.read_text())


def save_state(path: str, state: Dict[str, Any]) -> None:
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(state, ensure_ascii=False, indent=2))


def init_state(root: str, current: Optional[str] = None) -> Dict[str, Any]:
    current = current or root
    return {
        "root": root,
        "current": current,
        "stack": [],
        "liveMessageId": None,
        "menuVersion": 1,
        "lastCallback": None,
        "lastCallbackAt": None,
        "views": {}
    }


def push_path(state: Dict[str, Any], current: str, new_path: str) -> Dict[str, Any]:
    stack = state.setdefault("stack", [])
    if current:
        stack.append(current)
    state["current"] = new_path
    return state


def pop_path(state: Dict[str, Any]) -> Optional[str]:
    stack = state.setdefault("stack", [])
    if not stack:
        return None
    prev = stack.pop()
    state["current"] = prev
    return prev


def set_live_message_id(state: Dict[str, Any], message_id: Optional[object]) -> Dict[str, Any]:
    state["liveMessageId"] = None if message_id is None else str(message_id)
    return state


def bump_menu_version(state: Dict[str, Any]) -> Dict[str, Any]:
    state["menuVersion"] = int(state.get("menuVersion", 0)) + 1
    return state


def remember_callback(state: Dict[str, Any], callback: str) -> Dict[str, Any]:
    state["lastCallback"] = callback
    state["lastCallbackAt"] = time.time()
    return state


def is_duplicate_callback(state: Dict[str, Any], callback: str, window_seconds: float = 2.0) -> bool:
    last = state.get("lastCallback")
    at = state.get("lastCallbackAt")
    if last != callback or at is None:
        return False
    try:
        return (time.time() - float(at)) < window_seconds
    except Exception:
        return False

#!/usr/bin/env python3
import argparse
import json
from pathlib import Path


TEXT_EXTENSIONS = {
    ".md", ".txt", ".py", ".js", ".ts", ".json", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".sh", ".zsh", ".html", ".css", ".xml"
}


def looks_textual(path: Path) -> bool:
    if path.suffix.lower() in TEXT_EXTENSIONS:
        return True
    try:
        chunk = path.read_bytes()[:1024]
    except Exception:
        return False
    return b"\x00" not in chunk


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("path")
    ap.add_argument("--max-lines", type=int, default=80)
    ap.add_argument("--max-chars", type=int, default=4000)
    args = ap.parse_args()

    path = Path(args.path).expanduser().resolve()
    if not path.exists():
        raise SystemExit(json.dumps({"ok": False, "error": f"Not found: {path}"}, ensure_ascii=False))

    if path.is_dir():
        print(json.dumps({
            "ok": True,
            "kind": "directory",
            "path": str(path),
            "message": "Target is a directory"
        }, ensure_ascii=False, indent=2))
        return

    if not looks_textual(path):
        stat = path.stat()
        print(json.dumps({
            "ok": True,
            "kind": "binary",
            "path": str(path),
            "size": stat.st_size,
            "message": "Binary or unsupported file; prefer metadata/path output"
        }, ensure_ascii=False, indent=2))
        return

    text = path.read_text(errors="replace")
    lines = text.splitlines()
    clipped_lines = lines[:args.max_lines]
    clipped_text = "\n".join(clipped_lines)
    truncated = False
    if len(lines) > args.max_lines:
        truncated = True
    if len(clipped_text) > args.max_chars:
        clipped_text = clipped_text[:args.max_chars]
        truncated = True

    print(json.dumps({
        "ok": True,
        "kind": "text",
        "path": str(path),
        "preview": clipped_text,
        "lineCount": len(lines),
        "truncated": truncated
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import argparse
import json
from typing import Any, Dict, List, Optional


def make_button(text: str, callback_data: str, style: Optional[str] = None) -> Dict[str, Any]:
    button: Dict[str, Any] = {"text": text, "callback_data": callback_data}
    if style:
        button["style"] = style
    return button


def render_directory_buttons(view: Dict[str, Any], callback_prefix: str, include_back: bool = False, version: int = 1) -> List[List[Dict[str, Any]]]:
    rows: List[List[Dict[str, Any]]] = []
    for item in view.get("items", []):
        icon = "📁" if item.get("type") == "dir" else "📄"
        style = "primary" if item.get("type") == "dir" else None
        rows.append([make_button(f"{icon} {item.get('name')}", f"{callback_prefix}_v{version}_{item.get('id')}", style)])

    nav_row: List[Dict[str, Any]] = []
    if view.get("hasPrev"):
        nav_row.append(make_button("⬅️ 上一页", f"{callback_prefix}_v{version}_page_prev", "primary"))
    if view.get("hasNext"):
        nav_row.append(make_button("➡️ 下一页", f"{callback_prefix}_v{version}_page_next", "primary"))
    if nav_row:
        rows.append(nav_row)

    control_row: List[Dict[str, Any]] = []
    if include_back:
        control_row.append(make_button("⬅️ 返回上级", f"tfb_back_v{version}", "primary"))
    control_row.append(make_button("❌ 关闭", f"tfb_close_v{version}", "danger"))
    rows.append(control_row)
    return rows


def render_file_action_buttons(file_id: str, version: int = 1) -> List[List[Dict[str, Any]]]:
    return [
        [make_button("👁 预览", f"tfb_preview_v{version}_{file_id}", "primary")],
        [make_button("📋 路径", f"tfb_path_v{version}_{file_id}")],
        [make_button("⬇️ 下载", f"tfb_download_v{version}_{file_id}", "primary")],
        [make_button("⬅️ 返回", f"tfb_back_v{version}", "primary")],
        [make_button("❌ 关闭", f"tfb_close_v{version}", "danger")]
    ]


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("mode", choices=["directory", "file-actions"])
    ap.add_argument("input")
    ap.add_argument("--callback-prefix", default="tfb")
    ap.add_argument("--include-back", action="store_true")
    ap.add_argument("--file-id")
    args = ap.parse_args()

    if args.mode == "directory":
        view = json.loads(args.input)
        print(json.dumps(render_directory_buttons(view, args.callback_prefix, args.include_back), ensure_ascii=False, indent=2))
        return

    if args.mode == "file-actions":
        if not args.file_id:
            raise SystemExit("--file-id is required for file-actions mode")
        print(json.dumps(render_file_action_buttons(args.file_id), ensure_ascii=False, indent=2))
        return


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import argparse
import json
import re
from pathlib import Path
from typing import Optional


def load_state(path: Path) -> dict:
    return json.loads(path.read_text())


def find_item(state: dict, item_id: str) -> Optional[dict]:
    for view in state.get("views", {}).values():
        for item in view.get("items", []):
            if item.get("id") == item_id:
                return item
    return None


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("state_path")
    ap.add_argument("callback")
    args = ap.parse_args()

    state = load_state(Path(args.state_path))
    callback = args.callback.strip()
    state_version = int(state.get("menuVersion", 1))

    # Extract item_id from callback regardless of version.
    # Current formats:
    #   tfb_root_v{version}_{item_id}
    #   tfb_dir_{prefix}_v{version}_{item_id}
    item_id = None
    m = re.match(r"^tfb_root_v\d+_(w\d+)$", callback)
    if m:
        item_id = m.group(1)
    else:
        m = re.match(r"^tfb_dir_[^_]+_v\d+_([a-z\d]+)$", callback)
        if m:
            item_id = m.group(1)

    if item_id is not None:
        item = find_item(state, item_id)
        if item is not None:
            action = "open-dir" if item.get("type") == "dir" else "open-file-actions"
            print(json.dumps({"action": action, "item": item, "note": "processed despite version mismatch"}, ensure_ascii=False, indent=2))
            return

    # Check for navigation actions (back, close, page)
    # These need version match - if stale, just return stale
    simple_vm = re.match(r"^(tfb_(?:back|close))_v(\d+)$", callback)
    if simple_vm:
        base = simple_vm.group(1)
        cb_version = int(simple_vm.group(2))
        if cb_version != state_version:
            print(json.dumps({"action": "stale", "callback": callback, "stateVersion": state_version, "callbackVersion": cb_version}, ensure_ascii=False, indent=2))
            return
        callback = base
    else:
        vm = re.match(r"^(.*)_v(\d+)_(.+)$", callback)
        if vm:
            base = vm.group(1)
            cb_version = int(vm.group(2))
            suffix = vm.group(3)
            if cb_version != state_version:
                print(json.dumps({"action": "stale", "callback": callback, "stateVersion": state_version, "callbackVersion": cb_version}, ensure_ascii=False, indent=2))
                return
            callback = f"{base}_{suffix}"

    if callback == "tfb_back":
        print(json.dumps({"action": "back"}, ensure_ascii=False, indent=2))
        return
    if callback == "tfb_close":
        print(json.dumps({"action": "close"}, ensure_ascii=False, indent=2))
        return

    m = re.match(r"^(tfb_(?:root|dir_[^_]+))_page_(prev|next)$", callback)
    if m:
        print(json.dumps({"action": "page", "scope": m.group(1), "direction": m.group(2)}, ensure_ascii=False, indent=2))
        return

    m = re.match(r"^tfb_preview_(.+)$", callback)
    if m:
        item = find_item(state, m.group(1))
        print(json.dumps({"action": "preview", "item": item}, ensure_ascii=False, indent=2))
        return

    m = re.match(r"^tfb_path_(.+)$", callback)
    if m:
        item = find_item(state, m.group(1))
        print(json.dumps({"action": "path", "item": item}, ensure_ascii=False, indent=2))
        return

    m = re.match(r"^tfb_download_(.+)$", callback)
    if m:
        item = find_item(state, m.group(1))
        print(json.dumps({"action": "download", "item": item}, ensure_ascii=False, indent=2))
        return

    print(json.dumps({"action": "unknown", "callback": callback}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import argparse
import json
import subprocess
from pathlib import Path
from typing import Any, Dict, Optional

from file_browser_state import is_duplicate_callback, load_state, path_label, remember_callback, save_state
from browser_config import load_config

SCRIPT_DIR = Path(__file__).resolve().parent
CONTROLLER = SCRIPT_DIR / 'browser_controller.py'
RESOLVER = SCRIPT_DIR / 'resolve_callback.py'
PREVIEW = SCRIPT_DIR / 'preview_file.py'
DEFAULT_CONFIG_PATH = SCRIPT_DIR.parent / 'config.json'


def run_json(cmd: list[str]) -> Dict[str, Any]:
    out = subprocess.check_output(cmd, text=True)
    return json.loads(out)


def open_root(state_path: str, root: str, page_size: int = 12, config_path: Optional[str] = None) -> Dict[str, Any]:
    """
    Open the root directory and return a plan dict (Python object, not JSON string).
    Can be imported and used directly without JSON parsing.
    """
    if config_path is None:
        config_path = str(DEFAULT_CONFIG_PATH)

    state_path = str(Path(state_path).resolve())
    config = load_config(config_path)

    result = run_json([
        'python3', str(CONTROLLER), 'open-root', state_path,
        '--root', root,
        '--page-size', str(page_size)
    ])

    plan = build_send(result)
    plan['displayMode'] = config.get('displayMode', 'edit-message')
    return plan


def handle_callback(state_path: str, callback: str, page_size: int = 12, config_path: Optional[str] = None) -> Dict[str, Any]:
    """
    Handle a callback and return a plan dict (Python object, not JSON string).
    Can be imported and used directly without JSON parsing.
    """
    if config_path is None:
        config_path = str(DEFAULT_CONFIG_PATH)

    state_path = str(Path(state_path).resolve())
    config = load_config(config_path)

    state = load_state(state_path)
    if is_duplicate_callback(state, callback):
        return {
            'toolAction': 'noop',
            'message': f'duplicate callback ignored: {callback}',
            'state': state
        }

    resolution = run_json(['python3', str(RESOLVER), state_path, callback])
    action = resolution.get('action')

    if action == 'stale':
        remember_and_save(state_path, state, callback)
        return {
            'toolAction': 'noop',
            'message': f"stale callback ignored: {callback}",
            'state': state
        }

    if action == 'close':
        state = load_state(state_path) if Path(state_path).exists() else {}
        remember_and_save(state_path, state, callback)
        return {
            'toolAction': 'delete',
            'messageId': state.get('liveMessageId'),
            'state': state
        }

    state = load_state(state_path)
    live_message_id = state.get('liveMessageId')
    remember_and_save(state_path, state, callback)

    if action == 'back':
        result = run_json(['python3', str(CONTROLLER), 'back', state_path, '--page-size', str(page_size)])
        return build_navigation_plan(live_message_id, result, config.get('displayMode', 'edit-message'))

    if action == 'open-dir':
        item = resolution['item']
        result = run_json([
            'python3', str(CONTROLLER), 'open-dir', state_path,
            '--item-id', item['id'],
            '--page-size', str(page_size)
        ])
        return build_navigation_plan(live_message_id, result, config.get('displayMode', 'edit-message'))

    if action == 'open-file-actions':
        item = resolution['item']
        result = run_json([
            'python3', str(CONTROLLER), 'open-file-actions', state_path,
            '--item-id', item['id']
        ])
        return build_navigation_plan(live_message_id, result, config.get('displayMode', 'edit-message'))

    if action == 'preview':
        item = resolution.get('item')
        if not item:
            return {'toolAction': 'noop', 'message': 'preview target not found', 'state': state}
        preview = run_json(['python3', str(PREVIEW), item['path']])
        item_path_label = path_label(item['path'])
        if preview.get('kind') == 'text':
            body = preview.get('preview', '')
            if preview.get('truncated'):
                body += '\n\n（已截断）'
        else:
            body = preview.get('message', '无法预览该文件')
        return {
            'toolAction': 'send',
            'message': f"📄 `{item_path_label}`\n\n```\n{body}\n```",
            'replyTo': str(live_message_id),
            'state': load_state(state_path)
        }

    if action == 'path':
        item = resolution.get('item')
        if not item:
            return {'toolAction': 'noop', 'message': 'path target not found', 'state': state}
        return {
            'toolAction': 'send',
            'message': path_label(item['path']),
            'replyTo': str(live_message_id),
            'state': load_state(state_path)
        }

    if action == 'download':
        item = resolution.get('item')
        if not item:
            return {'toolAction': 'noop', 'message': 'download target not found', 'state': state}
        path = Path(item['path'])
        if not path.exists() or path.is_dir():
            return {
                'toolAction': 'send',
                'message': f"⚠️ 无法下载：目标不存在或是目录\n{path_label(item['path'])}",
                'replyTo': str(live_message_id),
                'state': load_state(state_path)
            }
        return {
            'toolAction': 'send-file',
            'path': str(path),
            'filename': path.name,
            'caption': f"⬇️ {path_label(item['path'])}",
            'replyTo': str(live_message_id),
            'state': load_state(state_path)
        }

    if action == 'page':
        result = run_json([
            'python3', str(CONTROLLER), 'page', state_path,
            '--direction', resolution['direction'],
            '--page-size', str(page_size)
        ])
        return build_navigation_plan(live_message_id, result, config.get('displayMode', 'edit-message'))

    return {
        'toolAction': 'noop',
        'message': f'Unknown callback: {callback}',
        'state': load_state(state_path)
    }


def build_send(result: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'toolAction': 'send',
        'message': result['text'],
        'buttons': result.get('buttons'),
        'viewType': result.get('kind'),
        'state': result.get('state', {})
    }


def build_navigation_plan(message_id: str, result: Dict[str, Any], display_mode: str) -> Dict[str, Any]:
    plan = {
        'toolAction': 'send',
        'message': result['text'],
        'buttons': result.get('buttons'),
        'viewType': result.get('kind'),
        'state': result.get('state', {}),
        'displayMode': display_mode,
        'replaceLiveMessage': True,
        'previousMessageId': str(message_id) if message_id is not None else None
    }
    if display_mode == 'edit-message':
        plan['cleanupPreviousMessage'] = True
        plan['cleanupMode'] = 'delete-after-send'
    return plan


def remember_and_save(state_path: str, state: Dict[str, Any], callback: str) -> Dict[str, Any]:
    remember_callback(state, callback)
    save_state(state_path, state)
    return state


def main() -> None:
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest='command', required=True)

    p_open = sub.add_parser('open-root')
    p_open.add_argument('state_path')
    p_open.add_argument('--root', required=True)
    p_open.add_argument('--page-size', type=int, default=12)
    p_open.add_argument('--config-path', default=str(DEFAULT_CONFIG_PATH))

    p_cb = sub.add_parser('handle-callback')
    p_cb.add_argument('state_path')
    p_cb.add_argument('callback')
    p_cb.add_argument('--page-size', type=int, default=12)
    p_cb.add_argument('--config-path', default=str(DEFAULT_CONFIG_PATH))

    args = ap.parse_args()

    if args.command == 'open-root':
        plan = open_root(
            args.state_path,
            args.root,
            args.page_size,
            args.config_path
        )
        print(json.dumps(plan, ensure_ascii=False, indent=2))
        return

    # handle-callback
    plan = handle_callback(
        args.state_path,
        args.callback,
        args.page_size,
        args.config_path
    )
    print(json.dumps(plan, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import argparse
import json
from typing import Any, Dict, Optional


def _fail(error: str) -> Dict[str, Any]:
    return {"ok": False, "error": error}


def validate_buttons(buttons: Any, view_type: Optional[str] = None) -> Dict[str, Any]:
    if buttons is None:
        return _fail("buttons is required for send plans")
    if isinstance(buttons, str):
        return _fail("buttons must be a real 2D array, not a JSON string")
    if not isinstance(buttons, list):
        return _fail("buttons must be a list of rows")
    if not buttons:
        return _fail("buttons must not be empty")

    for row_index, row in enumerate(buttons, start=1):
        if not isinstance(row, list):
            return _fail(f"row {row_index} must be a list")
        if not row:
            return _fail(f"row {row_index} must not be empty")
        for button_index, button in enumerate(row, start=1):
            if not isinstance(button, dict):
                return _fail(f"row {row_index} button {button_index} must be an object")
            if not button.get("text"):
                return _fail(f"row {row_index} button {button_index} is missing text")
            if not button.get("callback_data"):
                return _fail(f"row {row_index} button {button_index} is missing callback_data")
            if isinstance(button["callback_data"], str) and "/" in button["callback_data"]:
                return _fail(f"row {row_index} button {button_index} callback_data must stay opaque and must not contain raw paths")

    if view_type == "directory":
        for row_index, row in enumerate(buttons, start=1):
            first = row[0]
            callback = str(first.get("callback_data", ""))
            is_item_row = not ("_page_" in callback or callback.startswith("tfb_back_") or callback.startswith("tfb_close_"))
            if is_item_row and len(row) != 1:
                return _fail(f"viewType={view_type} requires one item per row; row {row_index} has {len(row)} buttons")

    if view_type == "file-actions":
        for row_index, row in enumerate(buttons, start=1):
            if len(row) != 1:
                return _fail(f"viewType={view_type} requires one action per row; row {row_index} has {len(row)} buttons")

    return {"ok": True, "rows": len(buttons)}


def build_message_payload(plan: Dict[str, Any]) -> Dict[str, Any]:
    tool_action = plan.get("toolAction")
    if tool_action != "send":
        return _fail(f"send_plan only supports toolAction=send, got {tool_action!r}")

    message = plan.get("message")
    if not isinstance(message, str) or not message:
        return _fail("message must be a non-empty string")

    view_type = plan.get("viewType")
    validation = validate_buttons(plan.get("buttons"), view_type=view_type)
    if not validation.get("ok"):
        return validation

    payload: Dict[str, Any] = {
        "action": "send",
        "message": message,
        "buttons": plan["buttons"],
    }
    if plan.get("replyTo") is not None:
        payload["replyTo"] = plan["replyTo"]

    return {
        "ok": True,
        "payload": payload,
        "meta": {
            "viewType": view_type,
            "rows": validation["rows"],
        }
    }


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("plan_json", help="JSON string for a run_browser_action.py plan")
    args = ap.parse_args()

    plan = json.loads(args.plan_json)
    print(json.dumps(build_message_payload(plan), ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import argparse
import json
import sys
from pathlib import Path

from send_plan import build_message_payload


def load_plan(path: str) -> dict:
    if path == "-":
        return json.load(sys.stdin)
    return json.loads(Path(path).read_text())


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("plan", help="Path to plan JSON, or - to read from stdin")
    args = ap.parse_args()

    result = build_message_payload(load_plan(args.plan))
    print(json.dumps(result, ensure_ascii=False, indent=2))
    if not result.get("ok"):
        raise SystemExit(1)


if __name__ == "__main__":
    main()
